import json

with open('data/modern-translation/t1251_part5.json', 'r', encoding='utf-8') as f:
    modern = json.load(f)

# 段181
modern[181] = "【善信守護與衣著】如果是善心的比丘、沙彌等受持我，我就會賜予大願。我是一切眾生的父、母，是財寶、辯才、多聞、智慧，是衣服、飲食，是方便之主、是良藥。又是這個大毒、大刀，是鎖輪、火輪、水輪、風輪。行者要這樣調心。如果我的受持人不壞威儀，恆常坐時披著赤色半袈裟，如果想要降伏怨家，先結印然後作護摩。【义解】本段講本尊對善心持法者的守護：作為眾生的父母，賜予財富、智慧、衣食、醫藥；同時也是忿怒的刀輪火水風輪，降伏惡人；要求行者常威儀不缺，披赤袈裟，降伏怨敵先結印再護摩。"
# 段182
modern[182] = "【藥叉降伏結界印】藥叉站立的金剛忿怒身印：右腿伸直，左腳踏在右足地上距離一肘左右，左手三指直立，用左手大拇指捻小指甲上叉腰，右手把五指放在臉上，用忿怒的聲音和神色結界、供壇、右轉，每轉一圈誦一遍咒，這樣做兩遍。咒說：「唵（一）　帝婆藥叉（二）【义解】本段講藥叉忿怒步的降伏結界印：右腳直、左腳踏地相距一肘，左手叉腰豎三指，右手覆面，忿怒聲右轉繞壇，一圈一咒，共轉兩圈。"
# 段183
modern[183] = "【結界功德與軍事降伏】「盤陀盤陀（三）　訶訶訶訶（四）　吽娑婆訶」「依靠這個印明法，就能成就如意結界，不需要其他雜念，法自然成就；如果不成就，問題在行人的心意。另外如果有戰事，國內動亂、人民不安，那時國王、大臣、王子、百官、宰相全都歸伏我一面十臂的多聞王，那時我就會讓對方軍主投降。【义解】本段給出藥叉結界印真言，說明此印能成如意結界，成否關鍵在行者一心；接著講國家戰亂時，國王大臣歸依本尊，本尊就能令敵軍投降。"
# 段184
modern[184] = "【軍陣降伏法】另外法如果想要降伏作亂的人，用小弓箭、大刀、堅木，以一當十、以十當百、以百當千、以千當萬。這樣知道對方軍人的數量，製作這些弓等，護摩七日、或者九日、二十一日、一百日，必定降伏。如果在王宮殿、或者深山、清淨的地方修這個法，那些敵人都會自然被箭射、被大刀砍、自然火燒而死。【义解】本段講軍陣降伏的具體修法：按照敵人數量製作弓箭刀木等兵器模型，在清淨處護摩7/9/21/100日，就能令敵軍自然被兵器、火燒消滅。"
# 段185
modern[185] = "【息災救國法】敵人降伏之後，各自回到本土。如果交戰的是兩國國王，就又讓他們發起慈悲利益的心，不再發生這樣的事。如果以至心按照軍事法，以及一切事行法，我會現身成就法。如果國內發生三災七難，萬民都不安樂，乃至死亡、天地不和，神鬼、先人亡靈都發恶心引發疫病。【义解】本段講降伏敵人之後，要令兩國國王生慈悲心，不再發動戰爭；如果國內發生天災人禍、疫病流行，本尊也會救護。"
# 段186
modern[186] = "【除災疫與增益】遇到這樣的災難，就觀想一國的人民，我修這個大密法，就會全部止息災難，增長人民的壽命和福分。天地神鬼、惡靈等，都以般若自在心令他們降伏，不讓他們再發作惡心。帝釋等天都懷著降伏心，這些災難一時全部消滅、疫病消滅。用青木香和水加持，再加持修法處所讓人飲用，國內人民就會得到無量壽命福德，沒有什麼可懷疑的。【义解】本段講救國除災法：觀想全國人民，修大密法止息災疫，以般若力降伏天地惡神，令其不作惡；加持青木香水分給人民飲用，人民得壽得福。"
# 段187
modern[187] = "【都鉢王與疫神】前面說過證入世界主都鉢王，以及若干牛頭羅剎鬼神等神都作為眷屬，全都令他們隨從。魔眾都不會違背天王的法教，如果違背這個政令，牛頭等神就會被般若火焚燒。沒有其他雜念，就會消滅疫病令人民安樂。給予眾生無量財寶，證入界的主尊就是疫神之主。為了利益眾生，才顯現這樣的相，對此不要有絲毫懷疑。【义解】本段說明證入界主都鉢王（牛頭天王）是統領疫神的首領，只要本尊下令，所有疫鬼都不敢違背，否則被般若火焚燒，因此能迅速消滅瘟疫，施與眾生財寶。"
# 段188
modern[188] = "【五王護摩與請召】如果有少許懷疑，就會失去大神驗。如果想要供養法、供養八曼茶羅界會諸尊，以及八牙天等供養，就能成就法。另外護摩的時候，還要觀想五大天王：中央是一面十臂本尊，東方提頭賴吒天，南方毘盧勒叉天王，西方毘盧博叉天王，北方最勝太子。【义解】本段再次強調不能生疑，生疑失驗；講供養八大曼荼羅與八牙天即可成就法；護摩時要觀五大天王：中為本尊，東方持國、南方增長、西方廣目、北方最勝太子（多聞）。"
# 段189
modern[189] = "【請尊高唱與彌勒壇】如果這樣修法的時候，阿闍梨放開聲音高唱。也就是說：「吽吃哩多陀迦野吽」「這就是請召聖尊、成就法的相。如果行法的時候，過了很久沒有靈驗，就再作隨心曼荼羅，中央是彌勒菩薩，左方法音輪菩薩，右方大妙相菩薩，四方是四大天王，那時我多聞天王就在北方，這樣修行就會成就。【义解】本段講護摩時阿闍梨要高唱請尊咒召喚聖眾；如果修法久無靈驗，就改作彌勒菩薩曼荼羅：中彌勒，左法音輪、右大妙相，四方四天王，本尊在北方，修之即得感應。"
# 段190
modern[190] = "【八曼陀羅與賊難】如果有八曼陀羅，就不需要再作這個曼陀羅用。如果受持八曼陀羅法，就等於受持一切法。如果在八曼陀羅前修行這個密法，就能得到如意成就，不要生懷疑。如果我這個本誓是虛假的，我就更不成正覺。如果有盜賊來搶走人物財物，財主只要至心念我，手持大刀，賊人就會降伏隨順，然後做七日護摩。【义解】本段強調八曼荼羅是總攝一切法的根本壇，在八曼荼羅前修法決定成就，本尊以不成佛為誓保證；遇到盜賊搶劫，至心念本尊持大刀，再做7日護摩，賊人必被降伏。"
# 段191
modern[191] = "【解咒救死與國王護法】如果有人被惡咒詛，就向著呪咀人的住宅方向，我面向那邊行降伏法，對方就會被降伏。如果人已經死了，就發慈悲心讓他活過來。如果是業報壽命盡了臨死，我做七日護摩供養，三天或者七天就能活過來。如果臥病很重已經沒有餘命，我做七日護摩供養，就會賜予無量財寶和壽命。如果惡人對佛弟子起壞心，聽到緣由之後，就作阿毘遮盧（降伏）法。【义解】本段講本法的不可思議功德：能解惡咒，甚至令業盡臨死者、重病將死者通過七日護摩延壽得寶；對惡人害佛弟子的，修降伏法懲治。"
# 段192
modern[192] = "【國王行政治理】同時時常諷誦真言，就能將這些惡人全部摧碎降伏，斷除他們的命根。如果有大災難，行人發起慈心，就成為息災。如果有惡人偷盜三寶物品，就對著三寶護法天諷誦，辨明緣由。如果有國王受持我、行我的法，我就會常常到他的地方，聽他的政事。如果有惡事，我就會轉動大王的心，讓國王轉惡政為善政，令國內人民生喜悅，加持國王沒有災難，大臣百官萬民也都是這樣。【义解】本段講惡人持續作惡就降伏斷命，發慈心即轉為息災；國王信奉修法，本尊會親自護持國政，令國王改惡從善，政治清明，國泰民安，君臣人民都無災難。"
# 段193
modern[193] = "【法師守護與毀法惡報】如果我捨棄本誓，我就不配叫護法天，也不成正覺。如果有法師受持我，天天禮拜，心清淨誦密語，我就會全都順從，他到什麼地方我都跟隨侍奉，現世就現童子形來承事、加以守護。如果法師、檀越等在受事修法時生起貪欲心，對供養等不清淨，就會失去法驗，現世舌切、手折、頭破、吐血，遭受大苦死亡。【义解】本段本尊以不成佛為誓，守護清淨說法的法師，甚至現童子身親自侍奉；但如果法師貪欲不清淨、受供不淨，就會失法驗，現世遭惡報死亡。"
# 段194
modern[194] = "【造像供養功德】又以清淨心行法，一切法都會成就，沒有什麼可懷疑的。如果製作佛像等，做工的人如果想要多要工錢，現世就會得到大蛇身，六根都不具足，常常受苦直到死亡。如果用間接的至心以香花供養，做這樣的事，不做就不成。造作佛像的功德，用佛作為師長的布施，哪怕只供養一朵妙花，這個功德都不會失去，如果不做就沒有功德。【义解】本段再次強調清淨心行法必成就；造像時工匠如果惡意勒索工錢會墮惡報，但虔誠供養哪怕一朵花的功德都不會唐捐，鼓勵大眾供養三寶。"
# 段195
modern[195] = "【謗法毀師惡報】對受法的法師起一次噁心，就不會成就法的功德，生生世世遇不到佛法僧，常隨惡道墮地獄。如果傳法給惡意、不守戒律的弟子，法就會全部滅盡無餘。這個法是世間希有的法，又是我的心眼。如果想要作大法印，只要作妙藏曼荼羅一界修行就可以成就。也可以在中央作釋迦牟尼佛說法的形像，左方是吉祥天，右方是毘沙門天王。【义解】本段講毀謗法師的惡報：生生世世不遇三寶、墮地獄；傳法給惡人/破戒人會令法滅盡；簡化修法時不必作全八曼荼羅，只作妙藏一界，或者中釋迦、左吉祥、右毘沙門的簡壇也能成就。"
# 段196
modern[196] = "【供養香華印】這樣的曼陀羅就是相應曼荼羅。另外成就法，如果要供養八曼陀羅，以及我的天王一切護法天，首先應當結香華印。二手的無名指、小指交叉，二中指指尖相柱，把二頭指放在中指背上，二大拇指按在頭指上。真言說：「唵摩拏阿羅地（一）【义解】本段說明簡化曼荼羅也是相應壇；接著講供養的第一個印：香華印的結法，用來供養香花。"
# 段197
modern[197] = "【香華飲食供養印】「鉢哆布羅迦（引）（二）　也薩薄賀（引）」「接著是飯食印。和前面的香華印一樣，只是把二小指、二無名指在掌中各分開。印真言說：「曩謨（引）惹岐帝（引）娑跛薩羅帝（引）哆吒羅哆吒羅攞延也悉婆薩嚩賀（引）」「這個契印以及真言，如果加持飲食供物奉獻，就能得到無盡大法寶藏。【义解】本段給出香華印真言，隨後講飲食供養印（和香華印大致相同，只是小指、無名指在掌中分開）與真言，加持飲食供養能得無盡寶藏。"
# 段198
modern[198] = "【空供養與燈印】如果沒有飲食，恆常在天王像前空結這個契印、誦真言供養天王，也能得到無盡福利。結令天王歡喜的法、藥、甘味、胡麻油燈印：右手的小指、無名指屈在掌中，中指伸直，頭指（食指）屈向掌心，用大拇指按在頭指上，大拇指尖貼在中指根部。真言說：【义解】本段講哪怕沒有實物供品，只要在像前結印誦咒做觀想供養，也能得無盡福報；接著講令天王歡喜的燈油供養印的結法，用來供胡麻油燈、甘味妙藥。"
# 段199
modern[199] = "【油燈供養印明】「唵婆閉底󰖊薩嚩賀（引）」「用這個契印、真言供養天王，觀想神力光照耀自在，就能得到天王歡喜。另外結阿遮盧迦（燈）印，也就是辛香油、苦華香油燈印。右手結內縛，地指（小指）豎立，用來供養百盞燈心。真言說：「唵度曳尼羅（二合引）【义解】本段給出藥燈印真言，說明以此印供燈能令天王歡喜；接著講燈供養的另一個印（阿遮盧迦燈印，內縛豎小指），用來供辛香花油燈百盞。"
# 段200
modern[200] = "【燈器與入壇印】「尾誐多野婆羅涕多（引）野吽增婆訶」「燈器就用金、銀、赤熟銅、瓦等其中隨便能得到的，拿新的乾淨布做燈炷。「接著是入三昧耶住壇場印。蓮華合掌，二大指分開豎起，隨著增婆訶的聲音各自來去。真言說：「唵誐婆尼（二合引）吽索婆賀（引）【义解】本段給出燈印真言，說明燈器材質隨緣使用，燈炷要用新淨布；隨後講入壇場的三昧耶印（蓮華合掌、大指開豎、隨咒動作）與真言。"

# 段201
modern[201] = "【降伏三昧耶與座印】」「阿毘舍盧迦三摩耶說：「唵阿三迷吽」「金剛座印。二手結內縛，八指節高起，二大拇指伸入內，就觀想是須彌山。真言說：「阿惡（二合）」「閼伽（淨水）印。蓮華合掌從中間打開，左右空指（大拇指）分開豎立。真言說：「曩謨三滿多冒他南佉㝹（二合引）【义解】本段給出降伏三昧耶真言；講金剛座印（內縛、八指高、大指入掌，觀須彌座）與單字真言；再講閼伽（淨水）供養印（開蓮華合掌、大指開豎）與真言。"
# 段202
modern[202] = "【塗香燒香道場印】婆尼吽索縛賀」「接著是塗香印。二手合掌，各個空指、風指尖合在一起，手掌大大仰起就成了。真言說：「唵地誐尼（二合）𭖘㝹野（二合）吽」「接著是燒香印。金剛合掌。真言說：「唵阿野佉多吽」「接著是淨道場印。二手內縛，左右手的地指、水指伸入掌中交叉，二大指頭互相直立。【义解】本段圓滿閼伽水真言，依次講塗香印（合掌、風空合、掌仰起）、燒香印（金剛合掌）與各自真言；隨後講淨道場印的結法（內縛、地水入掌交叉、大指直立）。"
# 段203
modern[203] = "【淨道場與遣魔印】右火指甲上按左空指，左火指甲上按右空指，二風指頭合在一起直立，印五處。同時要想菩提道場的所有污穢都被燒盡清淨。真言說：「藍」「接著結淨使印（淨除使者印）。左右手的地水火指在掌中交叉直立，左右風指頭合併伸直橫放延長，左右空指分開豎立，隨著索婆訶的聲音來去。真言說：【义解】本段補充淨道場印的細節（火指與空指相按、風指合立、印五處、燒盡穢污），給出單字種子真言「藍」；隨後講淨除障礙使者的印結法與動作。"
# 段204
modern[204] = "【數珠與息災供養】「多」「阿毘舍盧迦持數珠印。「右手的地指、風指直立，水、火、空指屈入內，就觀想成降伏體相使用，如果是雜香做的數珠也可以。真言說：「曩謨（一）　阿娑野（二合引）滿多那吽（二合引）增佉誐陀縛野唵（二）　吽（三）　曩褥（引）佉跨增木婆林野吽發吒素縛佉吽」【义解】本段給出淨使印單字真言「多」，隨後講降伏法持數珠印的結法（小指食指豎、餘三指入掌）、數珠材質（雜香珠也可）以及對應真言。"
# 段205
